import docx, re
d = docx.Document("output/offer_letter_filled.docx")
texts=[]
def walk_p(ps):
    for p in ps:
        texts.append("".join(r.text for r in p.runs))
def walk_tbl(t):
    for row in t.rows:
        for c in row.cells:
            walk_p(c.paragraphs)
            for nt in c.tables: walk_tbl(nt)
walk_p(d.paragraphs)
for t in d.tables: walk_tbl(t)
for s in d.sections:
    for part in (s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer):
        if part is None: continue
        walk_p(part.paragraphs)
        for t in part.tables: walk_tbl(t)
full="\n".join(texts)
left=re.findall(r"\{\{[^}]*\}\}", full)
print("leftover markers:", left)
print("has 'Lúcia Ahmed':", "Lúcia Ahmed" in full)
print("has RELOCATION content (7,750):", "7,750" in full)
print("mentions IF_RELOCATION:", "IF_RELOCATION" in full)
EOF
